// Format response for Data Tables API
const orders = $items('Fetch Orders').map(item => {
  const data = item.json;

  // Format currency fields with Peso sign
  if (data.total_amount) {
    data.total_amount_formatted = '₱' + parseFloat(data.total_amount).toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }
  if (data.new_can_total_amount) {
    data.new_can_total_amount_formatted = '₱' + parseFloat(data.new_can_total_amount).toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }
  if (data.refill_total_amount) {
    data.refill_total_amount_formatted = '₱' + parseFloat(data.refill_total_amount).toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }

  // Format date
  if (data.order_date) {
    data.order_date_formatted = new Date(data.order_date).toLocaleDateString('en-PH');
  }

  return data;
});

const total = $items('Count Total')[0]?.json?.total || 0;
const page = parseInt($json.query.page) || 1;
const limit = Math.min(parseInt($json.query.limit) || 10, 100);

return {
  data: orders,
  recordsTotal: total,
  recordsFiltered: total,
  page: page,
  limit: limit,
  totalPages: Math.ceil(total / limit),
  draw: parseInt($json.query.draw) || 1
};
